"""Inspect the task workspace: list files and dump SQLite database schema."""

import os
import sqlite3

BASE = os.path.dirname(os.path.abspath(__file__))


def find_databases():
    candidates = []
    for name in sorted(os.listdir(BASE)):
        full = os.path.join(BASE, name)
        if os.path.isfile(full) and name.lower().endswith(
            (".db", ".sqlite", ".sqlite3", ".sql3")
        ):
            candidates.append(full)
    return candidates


def main():
    print("Workspace:", BASE)
    print("--- contents ---")
    for name in sorted(os.listdir(BASE)):
        full = os.path.join(BASE, name)
        if os.path.isdir(full):
            print(f"[dir ] {name}/")
        else:
            print(f"[file] {name} ({os.path.getsize(full)} bytes)")

    print("--- databases ---")
    dbs = find_databases()
    if not dbs:
        print("No .db/.sqlite/.sqlite3/.sql3 file found in the workspace.")
        return

    for db_path in dbs:
        print(f"\nDatabase: {os.path.basename(db_path)}")
        try:
            with sqlite3.connect(db_path) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                print("Tables:", [r["name"] for r in tables])
                for table in tables:
                    tname = table["name"]
                    print(f"\n-- schema of {tname} --")
                    for row in cur.execute(f'PRAGMA table_info("{tname}")'):
                        print(
                            dict(row)
                        )
                    print(f"-- rows in {tname}: "
                          f"{cur.execute(f'SELECT COUNT(*) FROM \"{tname}\"').fetchone()[0]}")
                    print(f"-- sample rows from {tname} --")
                    for sample in cur.execute(f'SELECT * FROM "{tname}" LIMIT 3'):
                        print(dict(sample))
        except sqlite3.Error as exc:
            print("  ERROR reading database:", exc)


if __name__ == "__main__":
    main()

"""Task-local inspection helper: find SQLite databases in this folder and show their schema."""
import os
import sqlite3
import sys

HERE = os.path.dirname(os.path.abspath(__file__))

DB_EXTENSIONS = (".db", ".sqlite", ".sqlite3", ".db3")


def main() -> None:
    print("CWD:", os.getcwd())
    print("Script dir:", HERE)
    print("\nFiles in this folder:")
    for name in sorted(os.listdir(HERE)):
        full = os.path.join(HERE, name)
        if os.path.isfile(full):
            print(f"  FILE  {name} ({os.path.getsize(full)} bytes)")
        elif os.path.isdir(full):
            print(f"  DIR   {name}/")

    candidates = [
        os.path.join(HERE, name)
        for name in os.listdir(HERE)
        if os.path.isfile(os.path.join(HERE, name)) and name.lower().endswith(DB_EXTENSIONS)
    ]
    if not candidates:
        print("\nNo SQLite database file found in this folder.")
        return

    for path in candidates:
        print(f"\n===== Database: {os.path.basename(path)} =====")
        try:
            with sqlite3.connect(path) as conn:
                rows = conn.execute(
                    "SELECT type, name, sql FROM sqlite_master WHERE type IN ('table', 'index') ORDER BY type, name"
                ).fetchall()
                if not rows:
                    print("  (no tables/indexes)")
                for kind, name, sql in rows:
                    print(f"  [{kind}] {name}")
                    if sql:
                        for line in sql.splitlines():
                            print(f"      {line}")
        except sqlite3.Error as exc:
            print(f"  ERROR reading schema: {exc}", file=sys.stderr)


if __name__ == "__main__":
    main()

"""Task-local inspection helper: list workspace files and, if a SQLite
database is present, report its tables and columns.

This only reads local files / opens the local database read-only; it does
not modify anything.
"""
import os
import sqlite3
import sys

DB_EXTENSIONS = (".db", ".sqlite", ".sqlite3", ".db3")


def main() -> int:
    print("=== Files in workspace ===")
    for name in sorted(os.listdir(".")):
        print(f"  {name}")

    candidates = [
        name
        for name in os.listdir(".")
        if name.lower().endswith(DB_EXTENSIONS)
    ]
    if not candidates:
        print("\nNo SQLite database file found in this folder.")
        return 0

    for db_name in candidates:
        print(f"\n=== Database: {db_name} ===")
        try:
            # Read-only, immutable URI so inspection never writes to the DB.
            conn = sqlite3.connect(f"file:{db_name}?mode=ro", uri=True)
        except sqlite3.Error as exc:
            print(f"  could not open: {exc}")
            continue
        try:
            cur = conn.cursor()
            cur.execute(
                "SELECT name, sql FROM sqlite_master "
                "WHERE type IN ('table', 'view') ORDER BY name"
            )
            rows = cur.fetchall()
            if not rows:
                print("  (no tables or views)")
            for name, ddl in rows:
                print(f"  -- {name} --")
                print(f"  {ddl}")
                try:
                    cur.execute(f'PRAGMA table_info("{name}")')
                    cols = [(c[1], c[2]) for c in cur.fetchall()]
                    print(f"  columns: {cols}")
                except sqlite3.Error:
                    pass
        finally:
            conn.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())

